// Service configuration, loaded from an env-file style string.

export interface Config {
  port: number;
  host: string;
  appName: string;
  debug: boolean;
  motd: string;
}

const LINE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/;

// Parses KEY=VALUE lines. Values may be bare, single-quoted or double-quoted;
// quoted values keep whatever is inside them (including `#`), bare values are
// trimmed and lose any trailing ` # comment`.
export function parseEnvFile(text: string): Record<string, string> {
  const env: Record<string, string> = {};

  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;

    const match = LINE.exec(raw);
    if (!match) throw new Error(`invalid env line: ${line}`);
    const [, key, rest] = match;

    const quote = rest[0];
    if (quote === '"' || quote === "'") {
      const end = closingQuote(rest, quote);
      if (end === -1) throw new Error(`unterminated quote for ${key}`);
      const body = rest.slice(1, end);
      const trailing = rest.slice(end + 1).trim();
      if (trailing !== "" && !trailing.startsWith("#")) {
        throw new Error(`unexpected text after quoted value for ${key}`);
      }
      env[key] = quote === '"' ? unescape(body) : body;
    } else {
      env[key] = stripComment(rest).trim();
    }
  }

  return env;
}

// Index of the quote that closes the one at position 0, or -1. Backslash
// escapes only apply inside double quotes, matching shell/dotenv behaviour.
function closingQuote(rest: string, quote: string): number {
  for (let i = 1; i < rest.length; i++) {
    if (quote === '"' && rest[i] === "\\") {
      i++;
      continue;
    }
    if (rest[i] === quote) return i;
  }
  return -1;
}

function stripComment(value: string): string {
  const hash = value.indexOf("#");
  if (hash === -1) return value;
  // Only a `#` that starts a word is a comment; `a#b` stays intact.
  if (hash > 0 && !/\s/.test(value[hash - 1])) return value;
  return value.slice(0, hash);
}

function unescape(body: string): string {
  return body.replace(/\\([\\"'nrt])/g, (_, ch: string) => {
    switch (ch) {
      case "n":
        return "\n";
      case "r":
        return "\r";
      case "t":
        return "\t";
      default:
        return ch;
    }
  });
}

export function loadConfig(text: string): Config {
  const env = parseEnvFile(text);
  const port = Number(env.PORT ?? "8080");
  if (!Number.isInteger(port) || port <= 0) throw new Error(`invalid PORT: ${env.PORT}`);
  return {
    port,
    host: env.HOST ?? "127.0.0.1",
    appName: env.APP_NAME ?? "order-service",
    debug: (env.DEBUG ?? "false").toLowerCase() === "true",
    motd: env.MOTD ?? "",
  };
}

